-- BENCHMARK SEED: 512 dedicated load-test users (benchmark-only file; NOT
-- shipped with the server image and NOT loaded into dev databases by
-- setup-database -- benchmarks/fulla/setup.sh applies it to the bench DB).
-- Password: 'admin' (PBKDF2-SHA256, salt embedded in the hash string; the
-- users.salt column stays empty). No legacy verification window and no
-- login-time rehash involved; the setup warmup login just works.
-- DO NOT use these credentials in production!

-- 512 users, batch INSERT ... ON CONFLICT DO NOTHING.
ON CONFLICT (username) DO NOTHING;

-- Assign 'user' role to all 512 bench users.
SELECT u.id, r.id
FROM users u, roles r
WHERE u.username LIKE 'bench\_user\_%' AND r.name = 'user'
ON CONFLICT DO NOTHING;

-- Create subject mapping for all 512 bench users (provider 'local').
SELECT u.id::text, u.id, 'local'
FROM users u
WHERE u.username LIKE 'bench\_user\_%'
ON CONFLICT (provider, subject) DO NOTHING;
